{
  "title": "Experiences with relocation, job search, and language in Austria and Slovakia",
  "topics": [
    {
      "id": "relocation",
      "title": "Relocation and living locations",
      "claims": [
        {
          "text": "P1 has been living in Slovakia for almost a year.",
          "evidence": [43]
        },
        {
          "text": "P2 mentions that @AndriiRaccoon lives in Austria and walternet134 lives in Poland.",
          "evidence": [3]
        },
        {
          "text": "P2 reports that \"Mafiozia\" has returned to their native land.",
          "evidence": [4]
        },
        {
          "text": "P3 has been living in Austria since 17 November 2025.",
          "evidence": [49]
        },
        {
          "text": "P1 indicates they have been in Austria since early September 2025.",
          "evidence": [49, 54]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Job search abroad experiences",
      "claims": [
        {
          "text": "P3 recommends searching for jobs on LinkedIn.",
          "evidence": [18]
        },
        {
          "text": "P3 sent about 100 job applications and received only 3 interview invitations.",
          "evidence": [21]
        },
        {
          "text": "P3 observes that the biggest conversion ratio in the job market is getting an interview.",
          "evidence": [20]
        },
        {
          "text": "P3 began working in Austria on 2 March.",
          "evidence": [41]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements for jobs",
      "claims": [
        {
          "text": "95% of job vacancies require the local language.",
          "evidence": [26]
        },
        {
          "text": "Candidates lacking local language proficiency are often filtered out early.",
          "evidence": [27]
        },
        {
          "text": "Some companies hire candidates with limited knowledge of the local language.",
          "evidence": [29]
        },
        {
          "text": "Employers commonly request B2 level proficiency; B1 may be sufficient and certificates are rarely required.",
          "evidence": [46]
        },
        {
          "text": "P1 states that work is conducted in English, while neighbours speak Ukrainian.",
          "evidence": [44, 45]
        },
        {
          "text": "P3 is learning Slovak because of discomfort communicating in daily life and fear of being perceived as a migrant.",
          "evidence": [47]
        },
        {
          "text": "P1 feels uncertain about their Slovak language ability after a year in Slovakia.",
          "evidence": [43]
        }
      ]
    },
    {
      "id": "interview-experience",
      "title": "Interview experience and hiring rates",
      "claims": [
        {
          "text": "P3 secured a job within about two months of searching.",
          "evidence": [17]
        },
        {
          "text": "A friend of P3 with no commercial experience was invited to a mid‑level interview.",
          "evidence": [28]
        },
        {
          "text": "A candidate with three years of experience was also interviewed.",
          "evidence": [23]
        }
      ]
    },
    {
      "id": "salary-discussion",
      "title": "Salary expectations and offers",
      "claims": [
        {
          "text": "P3 believes salaries in Europe are generally higher than in Ukraine, though few pay attention to this difference.",
          "evidence": [35]
        },
        {
          "text": "P3's salary was higher than typical for the role, but they accepted the minimum increase due to urgency to find a job before early March.",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "job-search-tools",
      "title": "Tools and channels for job search and language practice",
      "claims": [
        {
          "text": "P1 plans to join Discord channels to practice English conversation.",
          "evidence": [56, 57]
        }
      ]
    },
    {
      "id": "staying-in-austria",
      "title": "Personal view on staying in Austria",
      "claims": [
        {
          "text": "P3 personally considers Austria the best choice among European countries for them.",
          "evidence": [60]
        },
        {
          "text": "P3's boyfriend, who has lived in Austria for over ten years, is not optimistic about the country's future.",
          "evidence": [60]
        },
        {
          "text": "P3 also considered Ireland, Norway, and Spain as possible relocation options.",
          "evidence": [60]
        }
      ]
    },
    {
      "id": "warsaw-event",
      "title": "Potential event in Warsaw",
      "claims": [
        {
          "text": "P3 is considering attending the Summer tech event in Warsaw (https://wawtech.io/summer).",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "P1 decides to try Discord channels for English conversational practice.",
      "evidence": [56, 57]
    }
  ],
  "openQuestions": [
    {
      "text": "Who lives in Bratislava or Slovakia, and who has moved abroad?",
      "evidence": [1]
    }
  ]
}
